import express, { type Express } from "express";
import fs from "fs";
import path from "path";
import { createServer as createViteServer, createLogger } from "vite";
import { type Server } from "http";
import viteConfig from "../vite.config";
import { nanoid } from "nanoid";

const viteLogger = createLogger();

export function log(message: string, source = "express") {
  const formattedTime = new Date().toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  console.log(`${formattedTime} [${source}] ${message}`);
}

export async function setupVite(app: Express, server: Server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true as const,
  };

  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    customLogger: {
      ...viteLogger,
      error: (msg, options) => {
        viteLogger.error(msg, options);
        process.exit(1);
      },
    },
    server: serverOptions,
    appType: "custom",
  });

  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;

    try {
      const clientTemplate = path.resolve(
        import.meta.dirname,
        "..",
        "client",
        "index.html",
      );

      // always reload the index.html file from disk incase it changes
      let template = await fs.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`,
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e as Error);
      next(e);
    }
  });
}

export function serveStatic(app: Express) {
  const distPath = path.resolve(import.meta.dirname, "public");

  if (!fs.existsSync(distPath)) {
    throw new Error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`,
    );
  }

  app.use(express.static(distPath));

  // fall through to index.html if the file doesn't exist
  app.use("*", (_req, res) => {
    res.sendFile(path.resolve(distPath, "index.html"));
  });
}

server/websocket.ts.content:
import { WebSocketServer, WebSocket } from 'ws';
import type { Server } from 'http';
import { storage } from './storage';

interface WSMessage {
  type: string;
  data: any;
  userId?: string;
  timestamp: number;
}

interface ConnectedUser {
  ws: WebSocket;
  memberId: string;
  memberName: string;
}

export function setupWebSocket(server: Server) {
  const wss = new WebSocketServer({ server, path: '/ws' });
  const connectedUsers = new Map<string, ConnectedUser>();

  wss.on('connection', (ws: WebSocket, req) => {
    console.log('New WebSocket connection');

    ws.on('message', async (data) => {
      try {
        const message: WSMessage = JSON.parse(data.toString());

        switch (message.type) {
          case 'user_connect':
            const { memberId, memberName } = message.data;
            connectedUsers.set(memberId, { ws, memberId, memberName });

            // Update member status to online
            await storage.updateTeamMember(memberId, { status: 'online' });

            // Broadcast user online status
            broadcast({
              type: 'user_status_changed',
              data: { memberId, memberName, status: 'online' },
              timestamp: Date.now(),
            });
            break;

          case 'chat_message':
            // Store chat message
            const chatMessage = await storage.createChatMessage({
              content: message.data.content,
              senderId: message.data.senderId,
              channelId: message.data.channelId,
              messageType: 'text',
            });

            // Broadcast to all connected users in the channel
            broadcast({
              type: 'new_chat_message',
              data: chatMessage,
              timestamp: Date.now(),
            });
            break;

          case 'task_updated':
            // Broadcast task updates to all users
            broadcast({
              type: 'task_updated',
              data: message.data,
              timestamp: Date.now(),
            });
            break;

          case 'timer_started':
            // Broadcast timer start
            broadcast({
              type: 'timer_started',
              data: message.data,
              timestamp: Date.now(),
            });
            break;

          case 'request_dashboard_update':
            // Send fresh dashboard data to requesting client
            try {
              const dashboardStats = await storage.getDashboardStats();
              const teamStats = await storage.getTeamStats();

              ws.send(JSON.stringify({
                type: 'dashboard_update',
                data: { dashboardStats, teamStats },
                timestamp: Date.now(),
              }));
            } catch (error) {
              console.error('Error sending dashboard update:', error);
            }
            break;

          case 'request_team_update':
            // Send fresh team data to requesting client
            try {
              const teamStats = await storage.getTeamStats();

              ws.send(JSON.stringify({
                type: 'team_update',
                data: teamStats,
                timestamp: Date.now(),
              }));
            } catch (error) {
              console.error('Error sending team update:', error);
            }
            break;

          case 'timer_stopped':
            // Broadcast timer stop
            broadcast({
              type: 'timer_stopped',
              data: message.data,
              timestamp: Date.now(),
            });
            break;

          case 'project_updated':
            // Broadcast project updates
            broadcast({
              type: 'project_updated',
              data: message.data,
              timestamp: Date.now(),
            });
            break;

          case 'ping':
            // Respond to ping with pong
            ws.send(JSON.stringify({
              type: 'pong',
              timestamp: Date.now(),
            }));
            break;
        }
      } catch (error) {
        console.error('WebSocket message error:', error);
        ws.send(JSON.stringify({
          type: 'error',
          data: { message: 'Invalid message format' },
          timestamp: Date.now(),
        }));
      }
    });

    ws.on('close', async () => {
      // Find and remove user from connected users
      for (const [memberId, user] of Array.from(connectedUsers.entries())) {
        if (user.ws === ws) {
          connectedUsers.delete(memberId);

          // Update member status to offline
          await storage.updateTeamMember(memberId, { status: 'offline' });

          // Broadcast user offline status
          broadcast({
            type: 'user_status_changed',
            data: { memberId, memberName: user.memberName, status: 'offline' },
            timestamp: Date.now(),
          });
          break;
        }
      }
    });

    ws.on('error', (error) => {
      console.error('WebSocket error:', error);
    });
  });

  function broadcast(message: WSMessage, excludeUserId?: string) {
    const messageString = JSON.stringify(message);

    connectedUsers.forEach((user, memberId) => {
      if (excludeUserId && memberId === excludeUserId) return;

      if (user.ws.readyState === WebSocket.OPEN) {
        user.ws.send(messageString);
      }
    });
  }

  // Send periodic dashboard updates every 30 seconds
  setInterval(async () => {
    try {
      const dashboardStats = await storage.getDashboardStats();
      const teamStats = await storage.getTeamStats();

      broadcast({
        type: 'auto_dashboard_update',
        data: { dashboardStats, teamStats },
        timestamp: Date.now(),
      });
    } catch (error) {
      console.error('Error sending periodic updates:', error);
    }
  }, 30000); // Every 30 seconds

  // Send heartbeat to keep connections alive
  setInterval(() => {
    broadcast({
      type: 'heartbeat',
      data: { connectedUsers: Array.from(connectedUsers.keys()) },
      timestamp: Date.now(),
    });
  }, 60000); // Every 60 seconds
}

shared/schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  index,
  jsonb,
  pgTable,
  timestamp,
  varchar,
  text,
  integer,
  boolean,
  decimal,
  uuid,
} from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Session storage table (mandatory for Replit Auth)
export const sessions = pgTable(
  "sessions",
  {
    sid: varchar("sid").primaryKey(),
    sess: jsonb("sess").notNull(),
    expire: timestamp("expire").notNull(),
  },
  (table) => [index("IDX_session_expire").on(table.expire)],
);

// User storage table (mandatory for Replit Auth)
export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: varchar("email").unique(),
  firstName: varchar("first_name"),
  lastName: varchar("last_name"),
  profileImageUrl: varchar("profile_image_url"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Jo'Fé Digital team members
export const teamMembers = pgTable("team_members", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  role: varchar("role").notNull(),
  username: varchar("username").notNull().unique(),
  isAdmin: boolean("is_admin").default(false),
  hourlyRate: decimal("hourly_rate", { precision: 10, scale: 2 }).default('5000'),
  skills: text("skills").array(),
  status: varchar("status").default('offline'), // online, offline, busy, away
  avatar: varchar("avatar"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Clients
export const clients = pgTable("clients", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  type: varchar("type"), // sector/industry
  contactPerson: varchar("contact_person"),
  email: varchar("email"),
  phone: varchar("phone"),
  address: text("address"),
  monthlyBudget: decimal("monthly_budget", { precision: 12, scale: 2 }),
  contractEndDate: timestamp("contract_end_date"),
  satisfaction: decimal("satisfaction", { precision: 3, scale: 2 }).default('0'), // 0-5 rating
  totalRevenue: decimal("total_revenue", { precision: 12, scale: 2 }).default('0'),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Projects
export const projects = pgTable("projects", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  description: text("description"),
  clientId: varchar("client_id").references(() => clients.id),
  status: varchar("status").default('planning'), // planning, active, paused, completed, cancelled
  priority: varchar("priority").default('moyenne'), // basse, moyenne, haute, urgente
  budget: decimal("budget", { precision: 12, scale: 2 }),
  actualCost: decimal("actual_cost", { precision: 12, scale: 2 }).default('0'),
  progress: integer("progress").default(0), // 0-100
  startDate: timestamp("start_date"),
  endDate: timestamp("end_date"),
  deadline: timestamp("deadline"),
  createdBy: varchar("created_by").references(() => teamMembers.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Tasks
export const tasks = pgTable("tasks", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  description: text("description"),
  projectId: varchar("project_id").references(() => projects.id),
  clientId: varchar("client_id").references(() => clients.id),
  assignedTo: varchar("assigned_to").references(() => teamMembers.id),
  status: varchar("status").default('en_attente'), // en_attente, en_cours, en_pause, termine, annule
  priority: varchar("priority").default('moyenne'), // basse, moyenne, haute, urgente
  progress: integer("progress").default(0), // 0-100
  estimatedHours: decimal("estimated_hours", { precision: 8, scale: 2 }),
  actualHours: decimal("actual_hours", { precision: 8, scale: 2 }).default('0'),
  hourlyRate: decimal("hourly_rate", { precision: 10, scale: 2 }),
  totalCost: decimal("total_cost", { precision: 12, scale: 2 }).default('0'),
  deadline: timestamp("deadline"),
  isTimerActive: boolean("is_timer_active").default(false),
  timerStartedAt: timestamp("timer_started_at"),
  totalTimeSpent: integer("total_time_spent").default(0), // in seconds
  createdBy: varchar("created_by").references(() => teamMembers.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Time tracking entries
export const timeEntries = pgTable("time_entries", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  taskId: varchar("task_id").references(() => tasks.id),
  memberId: varchar("member_id").references(() => teamMembers.id),
  startTime: timestamp("start_time").notNull(),
  endTime: timestamp("end_time"),
  duration: integer("duration").default(0), // in seconds
  description: text("description"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Chat messages
export const chatMessages = pgTable("chat_messages", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  content: text("content").notNull(),
  senderId: varchar("sender_id").references(() => teamMembers.id),
  channelId: varchar("channel_id").notNull(), // general, project-specific, etc.
  messageType: varchar("message_type").default('text'), // text, file, system
  fileUrl: varchar("file_url"),
  mentions: text("mentions").array(), // @username mentions
  createdAt: timestamp("created_at").defaultNow(),
});

// Chat channels
export const chatChannels = pgTable("chat_channels", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  type: varchar("type").default('project'), // general, project, direct
  projectId: varchar("project_id").references(() => projects.id),
  isPrivate: boolean("is_private").default(false),
  members: text("members").array(), // array of member IDs
  createdBy: varchar("created_by").references(() => teamMembers.id),
  createdAt: timestamp("created_at").defaultNow(),
});

// Notifications
export const notifications = pgTable("notifications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  recipientId: varchar("recipient_id").references(() => teamMembers.id),
  title: varchar("title").notNull(),
  message: text("message").notNull(),
  type: varchar("type").notNull(), // task_assigned, deadline_approaching, mention, etc.
  isRead: boolean("is_read").default(false),
  relatedId: varchar("related_id"), // ID of related task/project/etc
  createdAt: timestamp("created_at").defaultNow(),
});

// Performance metrics
export const performanceMetrics = pgTable("performance_metrics", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  memberId: varchar("member_id").references(() => teamMembers.id),
  month: integer("month").notNull(),
  year: integer("year").notNull(),
  tasksCompleted: integer("tasks_completed").default(0),
  totalHours: decimal("total_hours", { precision: 8, scale: 2 }).default('0'),
  revenue: decimal("revenue", { precision: 12, scale: 2 }).default('0'),
  performanceScore: decimal("performance_score", { precision: 5, scale: 2 }).default('0'), // 0-100
  qualityScore: decimal("quality_score", { precision: 5, scale: 2 }).default('0'), // 0-100
  createdAt: timestamp("created_at").defaultNow(),
});

// Relations
export const teamMembersRelations = relations(teamMembers, ({ many }) => ({
  tasks: many(tasks),
  timeEntries: many(timeEntries),
  sentMessages: many(chatMessages),
  createdProjects: many(projects),
  notifications: many(notifications),
  performanceMetrics: many(performanceMetrics),
}));

export const clientsRelations = relations(clients, ({ many }) => ({
  projects: many(projects),
  tasks: many(tasks),
}));

export const projectsRelations = relations(projects, ({ one, many }) => ({
  client: one(clients, { fields: [projects.clientId], references: [clients.id] }),
  creator: one(teamMembers, { fields: [projects.createdBy], references: [teamMembers.id] }),
  tasks: many(tasks),
  chatChannel: one(chatChannels),
}));

export const tasksRelations = relations(tasks, ({ one, many }) => ({
  project: one(projects, { fields: [tasks.projectId], references: [projects.id] }),
  client: one(clients, { fields: [tasks.clientId], references: [clients.id] }),
  assignee: one(teamMembers, { fields: [tasks.assignedTo], references: [teamMembers.id] }),
  creator: one(teamMembers, { fields: [tasks.createdBy], references: [teamMembers.id] }),
  timeEntries: many(timeEntries),
}));

export const timeEntriesRelations = relations(timeEntries, ({ one }) => ({
  task: one(tasks, { fields: [timeEntries.taskId], references: [tasks.id] }),
  member: one(teamMembers, { fields: [timeEntries.memberId], references: [teamMembers.id] }),
}));

export const chatMessagesRelations = relations(chatMessages, ({ one }) => ({
  sender: one(teamMembers, { fields: [chatMessages.senderId], references: [teamMembers.id] }),
}));

export const chatChannelsRelations = relations(chatChannels, ({ one, many }) => ({
  project: one(projects, { fields: [chatChannels.projectId], references: [projects.id] }),
  creator: one(teamMembers, { fields: [chatChannels.createdBy], references: [teamMembers.id] }),
  messages: many(chatMessages),
}));

export const notificationsRelations = relations(notifications, ({ one }) => ({
  recipient: one(teamMembers, { fields: [notifications.recipientId], references: [teamMembers.id] }),
}));

export const performanceMetricsRelations = relations(performanceMetrics, ({ one }) => ({
  member: one(teamMembers, { fields: [performanceMetrics.memberId], references: [teamMembers.id] }),
}));

// Insert schemas
export const insertTeamMemberSchema = createInsertSchema(teamMembers).omit({ id: true, createdAt: true, updatedAt: true });
export const insertClientSchema = createInsertSchema(clients).omit({ id: true, createdAt: true, updatedAt: true });
export const insertProjectSchema = createInsertSchema(projects).omit({ id: true, createdAt: true, updatedAt: true });
export const insertTaskSchema = createInsertSchema(tasks).omit({ id: true, createdAt: true, updatedAt: true });
export const insertTimeEntrySchema = createInsertSchema(timeEntries).omit({ id: true, createdAt: true });
export const insertChatMessageSchema = createInsertSchema(chatMessages).omit({ id: true, createdAt: true });
export const insertChatChannelSchema = createInsertSchema(chatChannels).omit({ id: true, createdAt: true });
