import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import type { Task, TeamMember, Client, Project } from '@shared/schema';

const taskSchema = z.object({
  name: z.string().min(1, 'Le nom de la tâche est requis'),
  description: z.string().optional(),
  projectId: z.string().optional(),
  clientId: z.string().optional(),
  assignedTo: z.string().optional(),
  priority: z.enum(['basse', 'moyenne', 'haute', 'urgente']).default('moyenne'),
  deadline: z.string().optional(),
  estimatedHours: z.string().optional(),
  hourlyRate: z.string().optional(),
});

type TaskFormData = z.infer<typeof taskSchema>;

interface TaskFormProps {
  task?: Task | null;
  onClose: () => void;
  onSubmit: () => void;
}

export function TaskForm({ task, onClose, onSubmit }: TaskFormProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: teamMembers = [] } = useQuery<TeamMember[]>({
    queryKey: ['/api/team-members'],
  });

  const { data: clients = [] } = useQuery<Client[]>({
    queryKey: ['/api/clients'],
  });

  const { data: projects = [] } = useQuery<Project[]>({
    queryKey: ['/api/projects'],
  });

  const form = useForm<TaskFormData>({
    resolver: zodResolver(taskSchema),
    defaultValues: {
      name: task?.name || '',
      description: task?.description || '',
      projectId: task?.projectId || '',
      clientId: task?.clientId || '',
      assignedTo: task?.assignedTo || '',
      priority: (task?.priority as any) || 'moyenne',
      deadline: task?.deadline ? new Date(task.deadline).toISOString().split('T')[0] : '',
      estimatedHours: task?.estimatedHours?.toString() || '',
      hourlyRate: task?.hourlyRate?.toString() || '',
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: TaskFormData) => {
      const taskData = {
        ...data,
        deadline: data.deadline ? new Date(data.deadline).toISOString() : null,
        estimatedHours: data.estimatedHours ? parseFloat(data.estimatedHours) : null,
        hourlyRate: data.hourlyRate ? parseFloat(data.hourlyRate) : null,
      };

      if (task) {
        await apiRequest('PUT', `/api/tasks/${task.id}`, taskData);
      } else {
        await apiRequest('POST', '/api/tasks', taskData);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/tasks'] });
      queryClient.invalidateQueries({ queryKey: ['/api/analytics/dashboard'] });
      toast({
        title: task ? "Tâche mise à jour" : "Tâche créée",
        description: task ? "La tâche a été mise à jour avec succès" : "La nouvelle tâche a été créée avec succès",
      });
      onSubmit();
    },
    onError: (error: Error) => {
      toast({
        title: "Erreur",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (data: TaskFormData) => {
    createMutation.mutate(data);
  };

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle data-testid="form-title">
          {task ? 'Modifier la tâche' : 'Créer une nouvelle tâche'}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Nom de la tâche *</FormLabel>
                    <FormControl>
                      <Input 
                        placeholder="Nom de la tâche" 
                        {...field} 
                        data-testid="input-task-name"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="assignedTo"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Assigné à</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger data-testid="select-assignee">
                          <SelectValue placeholder="Sélectionner un membre" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {teamMembers.map((member: TeamMember) => (
                          <SelectItem key={member.id} value={member.id}>
                            {member.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="clientId"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Client</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger data-testid="select-client">
                          <SelectValue placeholder="Sélectionner un client" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {clients.map((client: Client) => (
                          <SelectItem key={client.id} value={client.id}>
                            {client.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="projectId"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Projet</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger data-testid="select-project">
                          <SelectValue placeholder="Sélectionner un projet" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {projects.map((project: Project) => (
                          <SelectItem key={project.id} value={project.id}>
                            {project.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="priority"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Priorité</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger data-testid="select-priority">
                          <SelectValue />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="basse">Basse</SelectItem>
                        <SelectItem value="moyenne">Moyenne</SelectItem>
                        <SelectItem value="haute">Haute</SelectItem>
                        <SelectItem value="urgente">Urgente</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="deadline"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Échéance</FormLabel>
                    <FormControl>
                      <Input 
                        type="date" 
                        {...field} 
                        data-testid="input-deadline"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="estimatedHours"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Heures estimées</FormLabel>
                    <FormControl>
                      <Input 
                        type="number" 
                        step="0.5"
                        placeholder="0" 
                        {...field} 
                        data-testid="input-estimated-hours"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="hourlyRate"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Taux horaire (FR CFA)</FormLabel>
                    <FormControl>
                      <Input 
                        type="number" 
                        placeholder="5000" 
                        {...field} 
                        data-testid="input-hourly-rate"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="description"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Description</FormLabel>
                  <FormControl>
                    <Textarea 
                      placeholder="Description de la tâche" 
                      rows={3}
                      {...field} 
                      data-testid="textarea-description"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end space-x-4">
              <Button 
                type="button" 
                variant="outline" 
                onClick={onClose}
                data-testid="button-cancel"
              >
                Annuler
              </Button>
              <Button 
                type="submit" 
                disabled={createMutation.isPending}
                data-testid="button-submit"
              >
                {createMutation.isPending 
                  ? (task ? "Mise à jour..." : "Création...") 
                  : (task ? "Mettre à jour" : "Créer la tâche")
                }
              </Button>
            </div>
          </form>
        </Form>
      </CardContent>
    </Card>
  );
}

client/src/components/tasks/TasksTable.t.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Timer } from "@/components/common/Timer";
import { TaskForm } from "./TaskForm";
import { Edit2, Trash2, Activity, Clock, CheckCircle, Watch } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { Task, TeamMember, Client } from "@shared/schema";

export function TasksTable() {
  const [showTaskForm, setShowTaskForm] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: tasks = [], isLoading: tasksLoading } = useQuery<Task[]>({
    queryKey: ["/api/tasks"],
  });

  const { data: teamMembers = [] } = useQuery<TeamMember[]>({
    queryKey: ["/api/team-members"],
  });

  const { data: clients = [] } = useQuery<Client[]>({
    queryKey: ["/api/clients"],
  });

  const { data: dashboardStats } = useQuery<any>({
    queryKey: ["/api/analytics/dashboard"],
  });

  const deleteMutation = useMutation({
    mutationFn: async (taskId: string) => {
      await apiRequest("DELETE", `/api/tasks/${taskId}`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
      toast({
        title: "Tâche supprimée",
        description: "La tâche a été supprimée avec succès",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Erreur",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const formatTime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  const formatCurrency = (amount: number | string) => {
    const num = typeof amount === 'string' ? parseFloat(amount) : amount;
    return new Intl.NumberFormat('fr-FR', {
      style: 'currency',
      currency: 'XOF',
      minimumFractionDigits: 0,
    }).format(num).replace('XOF', 'FR CFA');
  };

  const formatDate = (date: string | Date | null) => {
    if (!date) return '-';
    const d = new Date(date);
    return d.toLocaleDateString('fr-FR');
  };

  const getPriorityVariant = (priority: string) => {
    switch (priority) {
      case 'urgente': return 'destructive';
      case 'haute': return 'secondary';
      case 'moyenne': return 'outline';
      default: return 'outline';
    }
  };

  const getStatusVariant = (status: string) => {
    switch (status) {
      case 'termine': return 'default';
      case 'en_cours': return 'secondary';
      case 'en_pause': return 'outline';
      default: return 'outline';
    }
  };

  const getMemberName = (memberId: string) => {
    const member = teamMembers.find((m: TeamMember) => m.id === memberId);
    return member?.name || 'Non assigné';
  };

  const getClientName = (clientId: string) => {
    const client = clients.find((c: Client) => c.id === clientId);
    return client?.name || 'Aucun client';
  };

  const getMemberInitials = (memberId: string) => {
    const member = teamMembers.find((m: TeamMember) => m.id === memberId);
    if (!member) return 'NA';
    return member.name.split(' ').map(n => n[0]).join('').substring(0, 2);
  };

  if (tasksLoading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {[...Array(4)].map((_, i) => (
            <Card key={i} className="p-6">
              <div className="animate-pulse space-y-3">
                <div className="h-4 bg-muted rounded w-1/2"></div>
                <div className="h-8 bg-muted rounded w-1/3"></div>
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card className="p-6 border border-border">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-muted-foreground">Tâches Actives</p>
              <p className="text-2xl font-bold text-foreground" data-testid="stat-active-tasks">
                {dashboardStats?.activeTasks || 0}
              </p>
            </div>
            <div className="w-12 h-12 bg-primary/10 rounded-lg flex items-center justify-center">
              <Activity className="w-6 h-6 text-primary" />
            </div>
          </div>
        </Card>

        <Card className="p-6 border border-border">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-muted-foreground">En Cours</p>
              <p className="text-2xl font-bold text-foreground" data-testid="stat-in-progress">
                {tasks.filter((t: Task) => t.status === 'en_cours').length}
              </p>
            </div>
            <div className="w-12 h-12 bg-secondary/10 rounded-lg flex items-center justify-center">
              <Clock className="w-6 h-6 text-secondary" />
            </div>
          </div>
        </Card>

        <Card className="p-6 border border-border">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-muted-foreground">Terminées Aujourd'hui</p>
              <p className="text-2xl font-bold text-foreground" data-testid="stat-completed-today">
                {dashboardStats?.completedToday || 0}
              </p>
            </div>
            <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center">
              <CheckCircle className="w-6 h-6 text-green-600" />
            </div>
          </div>
        </Card>

        <Card className="p-6 border border-border">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-muted-foreground">Temps Total</p>
              <p className="text-2xl font-bold text-foreground" data-testid="stat-total-time">
                {formatTime(dashboardStats?.totalTime || 0)}
              </p>
            </div>
            <div className="w-12 h-12 bg-purple-100 rounded-lg flex items-center justify-center">
              <Watch className="w-6 h-6 text-purple-600" />
            </div>
          </div>
        </Card>
      </div>

      {/* Task Creation Form */}
      {showTaskForm && (
        <TaskForm
          task={editingTask}
          onClose={() => {
            setShowTaskForm(false);
            setEditingTask(null);
          }}
          onSubmit={() => {
            setShowTaskForm(false);
            setEditingTask(null);
            queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
          }}
        />
      )}

      {/* Create Task Button */}
      <div className="flex justify-end">
        <Button
          onClick={() => setShowTaskForm(true)}
          className="bg-primary text-primary-foreground hover:bg-primary/90"
          data-testid="button-create-task"
        >
          <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Nouvelle Tâche
        </Button>
      </div>

      {/* Tasks Table */}
      <Card className="border border-border overflow-hidden">
        <div className="p-4 border-b border-border">
          <h3 className="text-lg font-semibold text-foreground">Tableau de Suivi des Tâches</h3>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full">
            <thead className="bg-muted">
              <tr>
                <th className="text-left p-4 text-sm font-medium text-foreground">Tâche</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Assigné</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Client</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Priorité</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Échéance</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Statut</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Temps</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Coût</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Progression</th>
                <th className="text-left p-4 text-sm font-medium text-foreground">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {tasks.length === 0 ? (
                <tr>
                  <td colSpan={10} className="p-8 text-center text-muted-foreground">
                    Aucune tâche trouvée. Créez votre première tâche pour commencer.
                  </td>
                </tr>
              ) : (
                tasks.map((task: Task) => (
                  <tr key={task.id} className="hover:bg-muted/50" data-testid={`row-task-${task.id}`}>
                    <td className="p-4">
                      <div className="font-medium text-foreground" data-testid={`text-task-name-${task.id}`}>
                        {task.name}
                      </div>
                      {task.description && (
                        <div className="text-sm text-muted-foreground" data-testid={`text-task-description-${task.id}`}>
                          {task.description}
                        </div>
                      )}
                    </td>
                    <td className="p-4">
                      <div className="flex items-center space-x-2">
                        <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center text-xs font-medium text-white">
                          {getMemberInitials(task.assignedTo || '')}
                        </div>
                        <span className="text-sm text-foreground" data-testid={`text-assignee-${task.id}`}>
                          {getMemberName(task.assignedTo || '')}
                        </span>
                      </div>
                    </td>
                    <td className="p-4">
                      <span className="text-sm text-foreground" data-testid={`text-client-${task.id}`}>
                        {getClientName(task.clientId || '')}
                      </span>
                    </td>
                    <td className="p-4">
                      <Badge variant={getPriorityVariant(task.priority || 'moyenne')} data-testid={`badge-priority-${task.id}`}>
                        {task.priority?.charAt(0).toUpperCase() + task.priority?.slice(1) || 'Moyenne'}
                      </Badge>
                    </td>
                    <td className="p-4">
                      <span className="text-sm text-foreground" data-testid={`text-deadline-${task.id}`}>
                        {formatDate(task.deadline)}
                      </span>
                    </td>
                    <td className="p-4">
                      <Badge variant={getStatusVariant(task.status || 'en_attente')} data-testid={`badge-status-${task.id}`}>
                        {task.status?.replace('_', ' ').charAt(0).toUpperCase() + task.status?.slice(1).replace('_', ' ') || 'En attente'}
                      </Badge>
                    </td>
                    <td className="p-4">
                      <div className="flex items-center space-x-2">
                        <span className="text-sm text-foreground" data-testid={`text-time-${task.id}`}>
                          {formatTime(task.totalTimeSpent || 0)}
                        </span>
                        <Timer 
                          taskId={task.id} 
                          isActive={task.isTimerActive || false}
                          canControl={true} // TODO: Check permissions
                        />
                      </div>
                    </td>
                    <td className="p-4">
                      <span className="text-sm text-foreground" data-testid={`text-cost-${task.id}`}>
                        {formatCurrency(task.totalCost || 0)}
                      </span>
                    </td>
                    <td className="p-4">
                      <div className="flex items-center space-x-2">
                        <div className="flex-1">
                          <Progress value={task.progress || 0} className="h-2" />
                        </div>
                        <span className="text-xs text-muted-foreground" data-testid={`text-progress-${task.id}`}>
                          {task.progress || 0}%
                        </span>
                      </div>
                    </td>
                    <td className="p-4">
                      <div className="flex items-center space-x-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            setEditingTask(task);
                            setShowTaskForm(true);
                          }}
                          data-testid={`button-edit-${task.id}`}
                        >
                          <Edit2 className="w-4 h-4 text-muted-foreground" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => deleteMutation.mutate(task.id)}
                          disabled={deleteMutation.isPending}
                          data-testid={`button-delete-${task.id}`}
                        >
                          <Trash2 className="w-4 h-4 text-muted-foreground" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

client/src/components/team/TeamView.tsx.content:
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Users, UserPlus, CheckCircle, Clock, TrendingUp } from 'lucide-react';
import type { TeamMember } from '@shared/schema';

export function TeamView() {
  const [showMemberForm, setShowMemberForm] = useState(false);

  const { data: teamMembers = [], isLoading: membersLoading } = useQuery<TeamMember[]>({
    queryKey: ['/api/team-members'],
  });

  const { data: teamStats } = useQuery<any>({
    queryKey: ['/api/analytics/team'],
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'online': return 'bg-green-500';
      case 'offline': return 'bg-gray-400';
      case 'busy': return 'bg-red-500';
      case 'away': return 'bg-yellow-500';
      default: return 'bg-gray-400';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'online': return 'En ligne';
      case 'offline': return 'Hors ligne';
      case 'busy': return 'Occupé';
      case 'away': return 'Absent';
      default: return 'Inconnu';
    }
  };

  const getMemberInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').substring(0, 2);
  };

  const formatCurrency = (amount: number | string) => {
    const num = typeof amount === 'string' ? parseFloat(amount) : amount;
    return new Intl.NumberFormat('fr-FR', {
      style: 'currency',
      currency: 'XOF',
      minimumFractionDigits: 0,
    }).format(num).replace('XOF', 'FR CFA');
  };

  if (membersLoading) {
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <h2 className="text-2xl font-bold text-foreground">Gestion d'Équipe</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {[...Array(4)].map((_, i) => (
            <Card key={i} className="p-6">
              <div className="animate-pulse space-y-3">
                <div className="h-12 w-12 bg-muted rounded-full"></div>
                <div className="h-4 bg-muted rounded w-3/4"></div>
                <div className="h-3 bg-muted rounded w-1/2"></div>
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-foreground">Gestion d'Équipe</h2>
        <Button
          onClick={() => setShowMemberForm(true)}
          className="bg-primary text-primary-foreground hover:bg-primary/90"
          data-testid="button-add-member"
        >
          <UserPlus className="w-4 h-4 mr-2" />
          Ajouter Membre
        </Button>
      </div>

      {/* Team Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card className="p-6 border border-border text-center">
          <div className="w-12 h-12 bg-primary/10 rounded-lg mx-auto mb-3 flex items-center justify-center">
            <Users className="w-6 h-6 text-primary" />
          </div>
          <p className="text-2xl font-bold text-foreground" data-testid="stat-total-members">
            {teamMembers.length}
          </p>
          <p className="text-sm text-muted-foreground">Membres Total</p>
        </Card>

        <Card className="p-6 border border-border text-center">
          <div className="w-12 h-12 bg-green-100 rounded-lg mx-auto mb-3 flex items-center justify-center">
            <CheckCircle className="w-6 h-6 text-green-600" />
          </div>
          <p className="text-2xl font-bold text-foreground" data-testid="stat-online-members">
            {teamStats?.onlineMembers || 0}
          </p>
          <p className="text-sm text-muted-foreground">En Ligne</p>
        </Card>

        <Card className="p-6 border border-border text-center">
          <div className="w-12 h-12 bg-yellow-100 rounded-lg mx-auto mb-3 flex items-center justify-center">
            <Clock className="w-6 h-6 text-yellow-600" />
          </div>
          <p className="text-2xl font-bold text-foreground" data-testid="stat-busy-members">
            {teamMembers.filter((m: TeamMember) => m.status === 'busy' || m.status === 'away').length}
          </p>
          <p className="text-sm text-muted-foreground">Occupés/Absents</p>
        </Card>

        <Card className="p-6 border border-border text-center">
          <div className="w-12 h-12 bg-purple-100 rounded-lg mx-auto mb-3 flex items-center justify-center">
            <TrendingUp className="w-6 h-6 text-purple-600" />
          </div>
          <p className="text-2xl font-bold text-foreground" data-testid="stat-avg-performance">
            87%
          </p>
          <p className="text-sm text-muted-foreground">Productivité Moyenne</p>
        </Card>
      </div>

      {/* Team Members Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {teamMembers.length === 0 ? (
          <div className="col-span-full">
            <Card className="p-12 text-center">
              <h3 className="text-lg font-medium text-foreground mb-2">Aucun membre d'équipe</h3>
              <p className="text-muted-foreground mb-4">
                Ajoutez des membres pour commencer la collaboration.
              </p>
              <Button onClick={() => setShowMemberForm(true)}>
                <UserPlus className="w-4 h-4 mr-2" />
                Ajouter un membre
              </Button>
            </Card>
          </div>
        ) : (
          teamMembers.map((member: TeamMember) => (
            <Card key={member.id} className="border border-border hover:shadow-lg transition-shadow" data-testid={`card-member-${member.id}`}>
              <CardContent className="p-6">
                <div className="flex items-start space-x-4">
                  <div className="relative">
                    <Avatar className="w-12 h-12">
                      <AvatarFallback className="bg-primary text-primary-foreground font-medium">
                        {getMemberInitials(member.name)}
                      </AvatarFallback>
                    </Avatar>
                    <div 
                      className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white ${getStatusColor(member.status || 'offline')}`}
                      title={getStatusLabel(member.status || 'offline')}
                    ></div>
                  </div>
                  <div className="flex-1">
                    <h3 className="font-semibold text-foreground" data-testid={`text-member-name-${member.id}`}>
                      {member.name}
                      {member.isAdmin && (
                        <Badge variant="secondary" className="ml-2 text-xs">Admin</Badge>
                      )}
                    </h3>
                    <p className="text-sm text-muted-foreground" data-testid={`text-member-role-${member.id}`}>
                      {member.role}
                    </p>
                    <div className="flex items-center space-x-2 mt-2">
                      <div className={`w-2 h-2 rounded-full ${getStatusColor(member.status || 'offline')}`}></div>
                      <span className="text-xs text-muted-foreground" data-testid={`text-member-status-${member.id}`}>
                        {getStatusLabel(member.status || 'offline')}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="mt-4 space-y-3">
                  <div className="flex justify-between text-sm">
                    <span className="text-muted-foreground">Taux horaire</span>
                    <span className="text-foreground font-medium" data-testid={`text-member-rate-${member.id}`}>
                      {formatCurrency(member.hourlyRate || 0)}/h
                    </span>
                  </div>

                  {member.skills && member.skills.length > 0 && (
                    <div>
                      <p className="text-sm text-muted-foreground mb-2">Compétences</p>
                      <div className="flex flex-wrap gap-1">
                        {member.skills.slice(0, 3).map((skill, index) => (
                          <Badge key={index} variant="outline" className="text-xs" data-testid={`badge-skill-${member.id}-${index}`}>
                            {skill}
                          </Badge>
                        ))}
                        {member.skills.length > 3 && (
                          <Badge variant="outline" className="text-xs">
                            +{member.skills.length - 3}
                          </Badge>
                        )}
                      </div>
                    </div>
                  )}

                  {/* Placeholder performance metrics */}
                  <div className="grid grid-cols-3 gap-2 text-center pt-3 border-t border-border">
                    <div>
                      <p className="text-lg font-semibold text-foreground" data-testid={`text-member-tasks-${member.id}`}>
                        12
                      </p>
                      <p className="text-xs text-muted-foreground">Tâches</p>
                    </div>
                    <div>
                      <p className="text-lg font-semibold text-foreground" data-testid={`text-member-hours-${member.id}`}>
                        35h
                      </p>
                      <p className="text-xs text-muted-foreground">Cette semaine</p>
                    </div>
                    <div>
                      <p className="text-lg font-semibold text-green-600" data-testid={`text-member-performance-${member.id}`}>
                        92%
                      </p>
                      <p className="text-xs text-muted-foreground">Performance</p>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {/* Role Distribution */}
      <Card className="border border-border">
        <CardHeader>
          <CardTitle>Répartition par Rôle</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {Array.from(new Set(teamMembers.map((m: TeamMember) => m.role))).map((role) => {
              const count = teamMembers.filter((m: TeamMember) => m.role === role).length;
              const percentage = (count / teamMembers.length) * 100;

              return (
                <div key={role} className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-foreground font-medium">{role}</span>
                    <span className="text-muted-foreground">{count} membre{count > 1 ? 's' : ''}</span>
                  </div>
                  <div className="w-full bg-muted rounded-full h-2">
                    <div 
                      className="bg-primary h-2 rounded-full" 
                      style={{ width: `${percentage}%` }}
                    ></div>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

