                        <button 
                          className="text-[var(--jofe-blue-medium)] hover:text-[var(--jofe-blue-deep)]"
                          data-testid={`button-export-${record.id}`}
                        >
                          <Download className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        </main>
        </div>
      </div>
    </div>
  );
}

