      {suffix && <span className="text-lg ml-1">{suffix}</span>}
    </div>

    {trend && (
      <div className={`flex items-center gap-2 text-sm ${
        trend === 'positive' ? 'text-[#93C954]' : trend === 'negative' ? 'text-[#F68C1F]' : 'text-[#3475BB]'
