                  border: 'none',
                  background: 'none',
                  color: activeTab === tab.id ? 'var(--jofe-blue-light)' : 'var(--jofe-blue-medium)',
                  cursor: 'pointer',
                  borderBottom: activeTab === tab.id ? '2px solid var(--jofe-blue-light)' : '2px solid transparent',
                  whiteSpace: 'nowrap',
                  fontWeight: '500'
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        {/* Tab Content */}
        <main style={{ padding: '24px' }}>
          <div style={{ animation: 'fadeIn 0.5s ease-in' }}>
            {renderTabContent()}
          </div>
        </main>
      </div>

      <style>{`
        @keyframes rotate {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        :root {
          --jofe-blue-deep: #162C54;
          --jofe-blue-night: #1A4278;
          --jofe-blue-medium: #3475BB;
          --jofe-blue-light: #37B6E9;
          --jofe-black: #000000;
          --jofe-gray: #EBECED;
          --jofe-white: #FFFFFF;
          --jofe-green: #93C954;
          --jofe-orange: #F68C1F;
        }
      `}</style>
    </div>
  );
}

export default ProjectDetail;
